previewCss:
.darma-loader-darma-b14-nesting-dolls { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #0284c7); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .82); display: flex; align-items: flex-end; justify-content: center; gap: 4%; }
.darma-loader-darma-b14-nesting-dolls span { position: relative; border-radius: 50% 50% 42% 42% / 56% 56% 44% 44%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); animation: darma-loader-darma-b14-nesting-dolls-doll-in calc(var(--loader-speed, 1s) * 3) ease-out infinite; }
.darma-loader-darma-b14-nesting-dolls span::before { content: ''; position: absolute; top: 7%; left: 21%; width: 58%; height: 32%; border-radius: 50%; background: radial-gradient(circle at 50% 66%, color-mix(in srgb, #fff 90%, var(--accent-2)), color-mix(in srgb, #fff 66%, var(--accent-2))); }
.darma-loader-darma-b14-nesting-dolls span::after { content: ''; position: absolute; bottom: 7%; left: 23%; width: 54%; height: 36%; border-radius: 46% 46% 38% 38%; background: var(--accent-2); }
.darma-loader-darma-b14-nesting-dolls span:nth-child(1) { width: 33%; height: 100%; }
.darma-loader-darma-b14-nesting-dolls span:nth-child(2) { width: 26%; height: 78%; animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b14-nesting-dolls span:nth-child(3) { width: 20%; height: 58%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
@keyframes darma-loader-darma-b14-nesting-dolls-doll-in { 0% { opacity: 0; transform: translateY(26%) scale(.6); } 12% { opacity: 1; transform: translateY(0) scale(1.06); } 20% { transform: translateY(0) scale(1); } 80% { opacity: 1; transform: translateY(0) scale(1); } 92%, 100% { opacity: 0; transform: translateY(26%) scale(.6); } }

